const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const display=name=>name.toLocaleLowerCase('pt-BR').replace(/(^|\s|–)([a-zà-ÿ])/g,(m,a,b)=>a+b.toLocaleUpperCase('pt-BR')).replace(/\b(Do|Da|De|Em|Das)\b/g,m=>m.toLowerCase());
